import React, { useMemo, useState } from "react";
import { Form, Field } from "react-final-form";
import type { Meta, StoryObj } from "@storybook/react";
import { Info, Visibility, VisibilityOff } from "@airbus/icons/react";

import {
  Button,
  Checkbox,
  Flex,
  FormControl,
  IconButton,
  Inline,
  Input,
  Select,
  Stack,
  Textarea,
} from "../components";

const meta: Meta = {
  title: "General/Forms/Examples",
};
export default meta;

type Story = StoryObj<typeof Form>;

export const Register: Story = {
  render: () => {
    const [showPassword, setShowPassword] = useState(false);
    const [form, setForm] = useState({
      username: "john",
      password: "A$*k",
      role: "manager",
      introduction: "",
    });
    const [emailSettings, setEmailSettings] = useState({
      notifications: false,
      newsletter: false,
    });
    const usernameValid = useMemo(() => {
      return form.username !== undefined && form.username.length > 0;
    }, [form.username]);
    const passwordValid = useMemo(() => {
      return form.password !== undefined && form.password.length >= 6;
    }, [form.password]);
    return (
      <div style={{ width: "520px", padding: "2rem" }}>
        <form>
          <FormControl
            label="Username"
            error={!usernameValid}
            errorText="Required"
            required
          >
            <Input
              value={form.username}
              onChange={(event) =>
                setForm({ ...form, username: event.target.value })
              }
            />
          </FormControl>
          <FormControl
            label="Password"
            error={!passwordValid}
            errorText="Must contain 6 alphanumeric characters"
            required
          >
            <Input
              value={form.password}
              onChange={(event) =>
                setForm({ ...form, password: event.target.value })
              }
              type={showPassword ? "text" : "password"}
              endAdornment={
                <IconButton
                  variant="ghost"
                  size="small"
                  onClick={() => setShowPassword(!showPassword)}
                >
                  {showPassword ? <Visibility /> : <VisibilityOff />}
                </IconButton>
              }
            />
          </FormControl>
          <FormControl
            label="Role"
            required
            labelAdornment={
              <IconButton size="xsmall" variant="ghost">
                <Info />
              </IconButton>
            }
          >
            <Select
              value={form.role}
              onChange={(event) =>
                setForm({ ...form, role: event.target.value })
              }
            >
              <option value="manager">Manager</option>
              <option value="designer">Designer</option>
              <option value="developer">Developer</option>
            </Select>
          </FormControl>
          <FormControl
            label="Introduction"
            placeholder="Introduce yourself here"
          >
            <Textarea
              rows="2"
              value={form.introduction}
              onChange={(event) =>
                setForm({ ...form, introduction: event.target.value })
              }
            />
          </FormControl>
          <FormControl label="Email settings" required>
            <Stack spacing="1-x">
              <Checkbox
                label="Send me notifications"
                checked={emailSettings.notifications}
                onChange={(event) => {
                  setEmailSettings({
                    ...emailSettings,
                    notifications: event.target.checked,
                  });
                }}
              />
              <Checkbox
                label="Send me monthly newsletter"
                checked={emailSettings.newsletter}
                onChange={(event) =>
                  setEmailSettings({
                    ...emailSettings,
                    newsletter: event.target.checked,
                  })
                }
              />
            </Stack>
          </FormControl>
          <Inline align="end">
            <Button
              type="submit"
              variant="primary"
              disabled={!usernameValid || !passwordValid}
              onClick={(event) => {
                window.alert(JSON.stringify(form));
                event.preventDefault();
              }}
            >
              REGISTER
            </Button>
          </Inline>
        </form>
      </div>
    );
  },
};

export const ReactFinalForm: Story = {
  render: () => {
    const [showPassword, setShowPassword] = useState(false);
    const onSubmit = (values: any) => {
      window.alert(JSON.stringify(values, null, 2));
    };
    const onValidate = (values: any) => {
      const errors: any = {};
      if (!values.login) {
        errors.login = "Required";
      }
      if (!values.password) {
        errors.password = "Required";
      } else if (values.password.length < 6) {
        errors.password = "Minimum 6 characters";
      }
      return errors;
    };
    const renderLogin = ({ input, meta }: any) => (
      <FormControl
        label="Username"
        required
        error={meta.touched && meta.error}
        errorText={meta.error}
      >
        <Input {...input} required />
      </FormControl>
    );
    const renderPassword = ({ input, meta }: any) => (
      <FormControl
        label="Password"
        required
        helpLinkLabel="Forgot password ?"
        onHelpLinkClick={(evt) => evt.preventDefault()}
        error={meta.touched && meta.error}
        errorText={meta.error}
      >
        <Input
          {...input}
          type={showPassword ? "text" : "password"}
          endAdornment={
            <IconButton
              variant="ghost"
              size="small"
              onClick={() => setShowPassword(!showPassword)}
            >
              {showPassword ? <Visibility /> : <VisibilityOff />}
            </IconButton>
          }
        />
      </FormControl>
    );
    return (
      <div style={{ width: "360px", padding: "2rem" }}>
        <Form
          onSubmit={onSubmit}
          validate={onValidate}
          render={({
            handleSubmit,
            form,
            invalid,
            submitting,
            pristine,
            values,
          }) => (
            <form onSubmit={handleSubmit}>
              <Field name="login" render={renderLogin} />
              <Field name="password" render={renderPassword} />
              <Field
                name="remember"
                type="checkbox"
                render={({ input, meta }) => (
                  <Checkbox label="Remember me" {...input} />
                )}
              />
              <Flex style={{ margin: "2rem 0" }} alignItems="stretch">
                <Button
                  variant="primary"
                  disabled={invalid || submitting || pristine}
                  style={{ width: "100%" }}
                >
                  LOGIN
                </Button>
              </Flex>
              <pre
                style={{
                  padding: "1rem",
                  background: "#f5f5f5",
                  border: "1px solid #c4c4c4",
                  fontSize: "small",
                }}
              >
                {`invalid: ${invalid} - pristine: ${pristine}\nvalues: ${JSON.stringify(
                  values,
                  null,
                  2
                )}`}
              </pre>
            </form>
          )}
        />
      </div>
    );
  },
};
